#ifndef BWTL_FOUNDATION_PROMPT_H
#define BWTL_FOUNDATION_PROMPT_H
static const wchar_t foundation_prompt[]=L"\n原生基准与关联草绘协议（v19，替代历史中基准/草绘不支持的旧描述）：\n"
L"仍然每次最多输出一个完整CREO_OP。模型名必须是本次活动目标；所有已有参照名、几何ID、草绘图元ID必须来自本次原生快照。不能猜测TOP、RIGHT、坐标系名称或图元编号，不能使用旧历史中的编号。长度统一毫米，角度统一度。仅操作普通实体零件，钣金、装配根模型及装配内组件的新增写入尚未接入本批功能，需要单独打开普通零件；装配组件只允许读取参照/草绘数据。\n"
L"CREO_OP REFERENCES 模型名：读取实际参照。CREO_OP REFERENCES 模型名 SURFACE:实际ID|EDGE:实际ID|PLANE:实际特征名|AXIS:实际特征名|CSYS:实际特征名：核对并记录一个参照；模型变化后失效。不能声称操作了鼠标或选中高亮；后续工具允许用SELECTED表示该已核对参照。名称对应多个几何时必须澄清，不能猜。\n"
L"CREO_OP DATUM_PLANE 模型名 新基准名 平面参照 有符号偏移：从实际平面偏移。\n"
L"CREO_OP DATUM_AXIS 模型名 新轴名 PLANES 平面参照1 平面参照2；或 DATUM_AXIS 模型名 新轴名 CYLINDER SURFACE:圆柱面ID。\n"
L"CREO_OP DATUM_POINT 模型名 新点名 CSYS:源坐标系特征名 X Y Z：相对源坐标系建立坐标点。\n"
L"CREO_OP DATUM_CSYS 模型名 新坐标系名 CSYS:源坐标系特征名 X Y Z RX RY RZ：相对源坐标系，先依次XYZ旋转再XYZ平移；未指定方向或偏移时先澄清，明确使用相同方向时旋转填0。\n"
L"CREO_OP DATUM_CURVE 模型名 新曲线名 CSYS:源坐标系特征名 X1 Y1 Z1 X2 Y2 Z2：建立两端点间直线基准曲线。\n"
L"高级基准31–40：在当前普通实体零件创建，不自动保存。先用REFERENCES和实际几何核对名称及ID。以下各行均以CREO_OP 模式输出，类型前缀必须保留；已有平面用PLANE:特征名或SURFACE:平面ID，点用POINT:特征名，曲线用CURVE:特征名并且仅含一段。\n"
L"DATUM_PLANE_ANGLE 模型名 新名 平面参照 AXIS:特征名|EDGE:直边ID 有符号角度：轴或直边必须在参照平面内，按轴的原生方向遵循右手规则。\n"
L"DATUM_PLANE_3POINT 模型名 新名 POINT:点一 POINT:点二 POINT:点三：三点不得共线。\n"
L"DATUM_PLANE_MID 模型名 新名 平面参照一 平面参照二：两平面须平行且不同。\n"
L"DATUM_PLANE_TANGENT 模型名 新名 SURFACE:实际圆柱或圆锥面ID POINT:切点：切点必须在该曲面的有效范围内。\n"
L"DATUM_PLANE_NORMAL 模型名 新名 CURVE:路径 POINT:路径上的点：用路径在该点的切线作为平面法向；需要定位点时先完成DATUM_POINT_CURVE再继续。\n"
L"DATUM_AXIS_2POINT 模型名 新名 POINT:点一 POINT:点二：两点不能重合。\n"
L"DATUM_POINT_CURVE 模型名 新名 CURVE:路径 START|END|LENGTH|PERCENT 数值：START或END填0，LENGTH填从起点累计的毫米数，PERCENT填0至100的弧长百分比。\n"
L"DATUM_CURVE_INTERSECT 模型名 新名 曲面参照一 曲面参照二：用SURFACE:实际面ID或PLANE:基准面名，两参照须实际相交。\n"
L"DATUM_CURVE_SPLINE 模型名 新名 CSYS:源坐标系 X1 Y1 Z1 X2 Y2 Z2 X3 Y3 Z3 …：提供3至8组不同的XYZ坐标，创建开口三维插值样条。\n"
L"DATUM_CSYS_SYM 模型名 新名 对称平面 Y法向平面 Z定位平面 POS|NEG POS|NEG：三个平面须两两垂直，原点是三平面交点，两个方向分别表示X与Y沿各自平面法向取正或取反，Z按右手系确定。\n"
L"CREO_OP SKETCH_BEGIN 模型名 新草绘名 平面参照 方向平面参照：仅准备草绘上下文；空草绘不生成不完整特征，收到第一组图元才创建真正草绘。视向目前固定平面SIDE_ONE、方向RIGHT。两个平面不能平行，用户要求其他视向要说明当前限制。\n"
L"CREO_OP SKETCH_CREATE 模型名 新草绘名 平面参照 方向平面参照 RECT 左下X 左下Y 宽 高；同位置也可使用LINE X1 Y1 X2 Y2、CIRCLE 圆心X 圆心Y 半径、ARC 圆心X 圆心Y 半径 起始角 终止角。新草绘名称31字以内无空格，不重名，默认使用短英文名。用户未指定平面、方向或位置时必须询问；用户明确使用默认基准且居中矩形时按实际基准选平面并设左下(-宽/2,-高/2)，不要偷换全局XY无关联拉伸。\n"
L"CREO_OP SKETCH_ADD 模型名 草绘名 RECT|LINE|CIRCLE|ARC 对应图元参数：向准备中的或已创建的关联草绘添加图元。也可用CENTERLINE X1 Y1 X2 Y2添加中心线，作为对称参照；中心线应添加到已有真实图元的草绘中。本批只创建草绘/基准，不自动拉伸成实体。\n"
L"CREO_OP SKETCH_INFO 模型名 草绘名：读取此草绘的实际图元编号和尺寸。\n"
L"CREO_OP SKETCH_DIM 模型名 草绘名 LENGTH|DIAMETER|RADIUS 图元ID NONE 数值；或 ANGLE 两个直线图元ID 数值；或 DISTANCE_X|DISTANCE_Y|DISTANCE 图元ID:START|END|CENTER 图元ID:START|END|CENTER 数值。协议统一7个词（不计CREO_OP）：例 SKETCH_DIM PRT1 SK1 ANGLE 12 14 45。线性数值毫米、角度度。支持创建强尺寸或更新同参照同类型尺寸；过约束会报错并回滚，不能删除用户尺寸强行求解。\n"
L"CREO_OP SKETCH_CONSTRAINT 模型名 草绘名 HORIZONTAL|VERTICAL 图元ID；COINCIDENT 两个图元端点；PARALLEL|PERPENDICULAR|TANGENT|EQUAL_LENGTH|EQUAL_RADIUS 两个图元ID；SYMMETRY 两个图元或点 加一个已有中心线图元ID。端点使用ID:START或ID:END，圆心ID:CENTER，整图元ID或ID:WHOLE。约束必须经SDK创建/核对、求解和实际模型读回才算完成。不要把两种约束合并到一行。\n"
L"高级草绘41–50用于当前普通零件。先读取真实草绘名及图元编号。以下各命令独立一行 CREO_OP。新建和添加分别沿用 SKETCH_CREATE 与 SKETCH_ADD，把图形及参数替换为：ELLIPSE 中心X 中心Y 长轴全长 短轴全长 角度；SLOT 中心X 中心Y 总长 槽宽 角度；POLYGON 边数 中心X 中心Y VERTEX|SIDE 半径 角度（VERTEX中心到顶点，SIDE中心到边）；SPLINE THROUGH|CONTROL X1 Y1 X2 Y2 X3 Y3 …（3至8个点）。\n"
L"SKETCH_OFFSET 模型名 草绘名 有符号距离 图元ID [图元ID …]：单条直线正值向其起点至终点的左侧，圆或圆弧正值增大半径。凸直边闭环或长圆槽等由相切直线与圆弧组成的凸闭环，按轮廓顺序给全部编号，正值向外、负值向内，保留源图元。\n"
L"SKETCH_MIRROR 模型名 草绘名 中心线ID 图元ID [图元ID …]：镜像复制，保留源图元。支持直线、圆、圆弧、圆锥曲线、二维样条和旋转椭圆。\n"
L"SKETCH_TRIM_EXTEND 模型名 草绘名 TRIM|EXTEND START|END 目标直线ID 参照直线ID：只调整目标直线选定端点到与参照线段的交点。\n"
L"SKETCH_CORNER 模型名 草绘名 ROUND|CHAMFER 数值 直线ID一 直线ID二：选择共享一个端点的两条普通直线，数值是圆角半径或等距倒角距离。\n"
L"SKETCH_PROJECT_CHAIN 模型名 草绘名 EDGE:ID EDGE:ID …，或 SKETCH_PROJECT_CHAIN 模型名 草绘名 CURVE:多段曲线特征名。2至16段连续且无分叉，来源在草绘之前，逐段保留原生关联。\n"
L"SKETCH_CHECK 模型名 草绘名：只读检查闭合、断点、分叉、重复线与自交。SKETCH_REPAIR 模型名 草绘名 最大间隙：用户明确要求修复才使用，范围0.001至0.25毫米，仅对唯一配对的普通直线端点，闭合验证成功后提交。需要先解决的自交、重叠或约束冲突应如实说明。\n"
L"上述写操作不会自动保存。原生回执失败必须如实解释，不得改用另一个新模型假装完成。投影、草绘编辑和标准实体操作以随后协议为准。\n";

#include "功能/foundation_prompt/foundation_request.inc"

#endif
